public static int sumLeaves(BinNode<Integer> t) {
    if (t == null) {
        return 0;
    }
    // עלה — אין לו בנים
    if (!t.hasLeft() && !t.hasRight()) {
        return t.getValue();
    }
    return sumLeaves(t.getLeft()) + sumLeaves(t.getRight());
}

